export async function createScene(engine, canvas, BABYLON) {
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.02, 0.02, 0.02, 1);

  const camera = new BABYLON.ArcRotateCamera("camera", -Math.PI / 2, BABYLON.Tools.ToRadians(54), 225, BABYLON.Vector3.Zero(), scene);
  camera.attachControl(canvas, true);
  camera.useAutoRotationBehavior = true;

  const light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);

  let sideCount = 200;
  const box = BABYLON.MeshBuilder.CreateBox("box", { size: 0.8 }, scene);
  const material = new BABYLON.StandardMaterial("mat", scene);
  material.diffuseColor = new BABYLON.Color3(0.1, 0.1, 0.1);
  material.emissiveColor = new BABYLON.Color3(0.3, 0.5, 1.0);
  box.material = material;

  const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");
  const panel = new BABYLON.GUI.StackPanel();
  panel.width = "250px";
  panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  panel.paddingLeft = "20px";
  panel.paddingTop = "20px";
  advancedTexture.addControl(panel);

  const countText = new BABYLON.GUI.TextBlock();
  countText.height = "30px";
  countText.color = "white";
  countText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  countText.text = "Instance Count: " + (sideCount * sideCount).toLocaleString();
  panel.addControl(countText);

  const sliderHeader = new BABYLON.GUI.TextBlock();
  sliderHeader.text = "Side Count: " + sideCount;
  sliderHeader.height = "30px";
  sliderHeader.color = "white";
  sliderHeader.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  panel.addControl(sliderHeader);

  const slider = new BABYLON.GUI.Slider();
  slider.minimum = 1;
  slider.maximum = 1000;
  slider.value = sideCount;
  slider.height = "20px";
  slider.width = "200px";
  slider.color = "#007acc";
  slider.onValueChangedObservable.add((value) => {
    sideCount = Math.floor(value);
    sliderHeader.text = "Side Count: " + sideCount;
    countText.text = "Instance Count: " + (sideCount * sideCount).toLocaleString();

    // 인스턴스 버퍼 갱신을 위해 다음 렌더 루프에서 새 배열을 할당하도록 유도
    updateBufferFlag = true;
  });
  panel.addControl(slider);

  // --- Toast Notification Logic ---
  const showToast = (message, color = "orange") => {
    const toast = new BABYLON.GUI.Rectangle();
    toast.width = "300px";
    toast.height = "40px";
    toast.cornerRadius = 10;
    toast.color = "white";
    toast.thickness = 1;
    toast.background = color;
    toast.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
    toast.top = "10%";
    toast.alpha = 0;
    advancedTexture.addControl(toast);

    const text = new BABYLON.GUI.TextBlock();
    text.text = message;
    text.color = "white";
    text.fontSize = 14;
    toast.addControl(text);

    // 간단한 페이드 인/아웃 애니메이션
    let alpha = 0;
    const interval = setInterval(() => {
      alpha += 0.1;
      toast.alpha = alpha;
      if (alpha >= 1) clearInterval(interval);
    }, 30);

    setTimeout(() => {
      const fadeOut = setInterval(() => {
        alpha -= 0.1;
        toast.alpha = alpha;
        if (alpha <= 0) {
          clearInterval(fadeOut);
          advancedTexture.removeControl(toast);
        }
      }, 30);
    }, 3000); // 3초 후 사라짐
  };

  let time = 0;
  let updateBufferFlag = true;
  let matricesData = new Float32Array(16 * sideCount * sideCount);
  let fpsCheckTimer = 0;
  let isWarningShowing = false;

  // 재사용할 객체들 (Garbage Collection 방지)
  const tempScale = new BABYLON.Vector3();
  const tempRotation = new BABYLON.Quaternion();
  const tempTranslation = new BABYLON.Vector3();
  const tempMatrix = new BABYLON.Matrix();

  scene.onBeforeRenderObservable.add(() => {
    const deltaTime = engine.getDeltaTime();
    time += deltaTime * 0.002;
    const currentFps = engine.getFps();

    // 성능 모니터링: 60프레임 기준 30FPS 이하로 떨어지는지 2초마다 체크
    fpsCheckTimer += deltaTime;
    if (fpsCheckTimer > 2000) {
      if (currentFps < 30 && !isWarningShowing && sideCount > 300) {
        showToast("⚠️ Performance Warning: Low FPS detected!");
        isWarningShowing = true;
        // 경고 중복 방지를 위해 10초 후 리셋
        setTimeout(() => (isWarningShowing = false), 10000);
      }
      fpsCheckTimer = 0;
    }

    const totalCount = sideCount * sideCount;
    if (updateBufferFlag) {
      matricesData = new Float32Array(16 * totalCount);
      updateBufferFlag = false;
    }

    // 루프 내 연산 최적화
    for (let x = 0; x < sideCount; x++) {
      for (let z = 0; z < sideCount; z++) {
        const idx = x * sideCount + z;
        const posX = x - sideCount / 2;
        const posZ = z - sideCount / 2;

        const distance = Math.sqrt(posX * posX + posZ * posZ) * 0.1;
        const y = Math.sin(time + distance) * 2;
        const scale = (Math.cos(time + distance) + 1.5) * 0.5;

        tempScale.set(scale, scale, scale);
        BABYLON.Quaternion.RotationYawPitchRollToRef(time * 0.5, 0, 0, tempRotation);
        tempTranslation.set(posX, y, posZ);

        BABYLON.Matrix.ComposeToRef(tempScale, tempRotation, tempTranslation, tempMatrix);
        tempMatrix.copyToArray(matricesData, idx * 16);
      }
    }
    box.thinInstanceSetBuffer("matrix", matricesData, 16);
  });

  const pipeline = new BABYLON.DefaultRenderingPipeline("default", true, scene, [camera]);
  pipeline.bloomEnabled = true;
  pipeline.bloomThreshold = 0.3;
  pipeline.bloomWeight = 0.2;
  pipeline.glowLayerEnabled = true;
  pipeline.glowLayer.intensity = 0.35;

  return scene;
}
